@functools.lru_cache(maxsize=None)
def euler_totient(n: int) -> int:
    if n == 1:
        return 1
    if n % 2 == 0:
        return n // 2
    totient = 1
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            exponent = 0
            while n % i == 0:
                n //= i
                exponent += 1
            totient *= (i ** (exponent - 1)) * (i - 1)
