def manhattan_distance(a, b, f, g):
    return abs(a - f) + abs(b - g) + abs(a - f) + abs(b - g)

def dijkstra(w, d, h, a, b, f, g):
    grid = [[[-1] * d for _ in range(w)] for _ in range(h)]

    pq = deque()
    pq.append((0, 0, a, b))
    grid[0][a][b] = 0

    while pq:
        dist, x, y, z = pq.popleft()

        for dx, dy in ((0, 1), (1, 0), (0, -1), (-1, 0)):
            nx, ny = x + dx * w, y + dy * d
