import heapq

def solve():
    import heapq

    def bfs(n):
        q = deque([(1, n, n)])
        seen = set()
        while q:
            pos, rem, gap = q.popleft()
            if pos + gap > rem:
                continue
            if pos + gap in seen:
                continue
            if pos + gap == rem:
                yield [pos] + list(bfs(rem - pos - gap))
            else:
                seen.add(pos + gap)
                for i in range(gap + 1, min(gap + gap, rem) + 1):
                    yield from bfs(rem - pos - i)
                    q.append((pos + i, rem, i))

