    stack = deque()
    for i, num in enumerate(arr):
        stack.append((i, num))
        while stack and stack[-1][1] < num:
            start, end = stack.pop()
            subsegments.append(arr[start:end+1])
        if stack:
            stack[-1][0] = i + 1
    for i in range(len(arr), len(arr) + 1):
        subsegments.append(arr[:i])
    return subsegments

def find_min_permutation(n, used):
    if n == 1:
        return [1]
    permutations = []
    for i in range(1, n+1):
        if not used[i]:
            subarr = find_min_permutation(n-1, used[:i] + used[i+1:])
            if subarr:
                for j in range(len(subarr)):
                    permutation = subarr[:j] + [i] + subarr[j:]
                    if is_permutation(permutation):
                        permutations.append(permutation)
    if not permutations:
        permutations = list(itertools.permutations(list(range(1, n+1))))
