import itertools

def next_permutation(perm):
    i = len(perm) - 2
    while i >= 0 and perm[i] >= perm[i + 1]:
        i -= 1
    if i == -1:
        perm.reverse()
        return False
    j = len(perm) - 1
    while perm[i] >= perm[j]:
        j -= 1
    perm[i], perm[j] = perm[j], perm[i]
    l, r = i + 1, len(perm) - 1
    while l < r:
        perm[l], perm[r] = perm[r], perm[l]
        l += 1
        r -= 1
    return True

def solve(n):
    if n <= 1:
        return [list(range(1, n + 1))]

    perms = [list(range(1, n + 1))]
    fixed = [len([i for j, i in enumerate(perms[-1]) if j == i])]

    while True:
        for perm in perms:
            if next_permutation(perm):
                new_fixed = len([i for j, i in enumerate(perm) if j == i])
                if new_fixed < fixed[-1]:
                    perms.append(perm)
                    fixed.append(new_fixed)
        else:
            break

    return perms[:min(len(perms), len(fixed))]

