input = sys.stdin.readline

def inf = float('inf')

def dijkstra(graph, start):
    dist = [inf] * len(graph)
    dist[start] = 0
    q = [(0, start)]

    while q:
        d, node = heapq.heappop(q)
        if dist[node] < d:
            continue

        for nbr, edge in enumerate(graph[node]):
            if dist[nbr] > dist[node] + edge:
                dist[nbr] = dist[node] + edge
                heapq.heappush(q, (dist[nbr], nbr))

