        for j in range(m):
            if i and j:
                graph[i][j].append((1, (i-1, j)))
                graph[i-1][j].append((1, (i, j)))
                if j < m-1:
                    graph[i][j+1].append((1, (i, j+2)))
                    graph[i][j].append((1, (i, j-1)))

    stanley_dist = dijkstra(graph, (1, 1))
    megans_dist = dijkstra(graph, (n, m))
