import collections
import sys

def solve():
    n = int(input())
    boxes = collections.defaultdict(int)
    for _ in range(n):
        x, y = map(int, input().split())
        if x:
            for i in range(1, x + 1):
                boxes[i, 0] = 1
        else:
            for i in range(1, y + 1):
                boxes[0, i] = 1

    def dfs(x, y, visited):
        key = (x, y, tuple(visited))
        if key in MEMOS:
            return MEMOS[key]
        if x == 0 and y == 0 and all(visited):
            return 0
        if x < 0 or y < 0 or x >= len(boxes) or y >= len(boxes):
            return float('inf')
        min_moves = float('inf')
        for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nx, ny = x + dx, y + dy
            if not visited[boxes[nx, ny]]:
                visited[boxes[nx, ny]] = 1
                moves = dfs(nx, ny, visited)
                min_moves = min(min_moves, moves + 1)
                visited[boxes[nx, ny]] = 0
        MEMOS[key] = min_moves
        return min_moves

    MEMOS = {}
    return dfs(1, 0, {boxes[1, 0]: 1})

