import itertools
import math
import sys
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def extended_euclidean(a, b):
    if b == 0:
        return (1, 0, a)
    else:
        g, y, x = extended_euclidean(b, a % b)
        return (g, x - (a // b) * x, y)

def mod_inv(a, m):
    g, x, _ = extended_euclidean(a, m)
    if g < 0:
        g, x = -g, -x
    return x % m

def max_cost_permutation():
