    if n <= 1:
        return 1, [1]

    d = 2
    max_cost = 0
    max_permutation = []

    for candidate_d in range(2, int(math.sqrt(n) + 1)):
        for perm in itertools.permutations(range(1, n + 1)):
            cost = sum(1 for i, j in enumerate(perm[1:]) if perm[i] * candidate_d == j)
            if cost > max_cost:
                max_cost = cost
                max_permutation = perm

        if max_cost % candidate_d == 0:
            gcd_val = gcd(candidate_d, max_cost // candidate_d)
            d = max(d, gcd_val)

    if d == 2:
        return 1, list(range(1, n + 1))

    inv_d = mod_inv(d, n)
    permutation = list(range(1, n + 1))
    for i, j in enumerate(permutation[1:]):
        permutation[i] *= inv_d
        permutation[i], permutation[j] = permutation[j], permutation[i]

    return d, permutation

