from collections import defaultdict

def floyd_warshall(graph):
    n = len(graph)
    dist = defaultdict(lambda: defaultdict(int))

    for i in range(n):
        dist[i][i] = 0

    for i in range(n):
        for j in range(i + 1, n):
            dist[i][j] = graph[i][j] + dist[i][j - 1] if i != j - 1 else graph[i][j]
            dist[j][i] = dist[i][j]

