```python
from itertools import combinations
from collections import defaultdict

def solve():
    n, grid = int(input()), [list(map(int, input().split())) for _ in range(n)]
    visited = [[False] * n for _ in range(n)]
    graph = defaultdict(list)

    def dfs(i, j):
        if not (0 <= i < n and 0 <= j < n):
            return
        if not grid[i][j] or visited[i][j]:
            return
        visited[i][j] = True
        for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            dfs(i + dx, j + dy)
        graph[grid[i][j]].append((i, j))

    for i, j in grid:
        dfs(i, j)

    cuts = 0
    for r, c in combinations(range(n), 2):
        for g in graph.values():
            intersect = set(g) & set(zip(r, c))
            if intersect:
                for g_i, g_j in intersect:
                    grid[g_i][g_j] = 0
                cuts += 1
                for g_i, g_j in graph[min(graph.keys())]:
                    grid[g_i][g_j] = 0
    return cuts

for _ in range(int(input())):
    print(solve())
```

This solution uses DFS to find connected components of grass and checks all possible combinations of rows and columns to find the ones that intersect with the connected components. Then it cuts the grass in those intersections. The time complexity is O(n^2) due to the DFS traversal and O(n^3) due to the combinations.

