import sys
from functools import lru_cache

def solve():
    n, m = map(int, sys.stdin.readline().strip().split())
    if n == 1 or m == 1:
        return 1

    a = [[i * m + j for j in range(1, m + 1)] for i in range(1, n + 1)]
    dp = [[0] * m for _ in range(n)]

    @lru_cache((n, m, 0, 0))
    def dfs(i, j, cost):
        if i == n - 1 and j == m - 1:
            return cost + a[i][j]

        cost_down = float('inf') if i + 1 > n or dp[i + 1][j] > cost + a[i][j] else dp[i + 1][j]
        cost_right = float('inf') if j + 1 > m or dp[i][j + 1] > cost + a[i][j] else dp[i][j + 1]
        return min(cost_down, cost_right)

    dp[1][1] = a[1][1]
    return dfs(1, 1, 0)

t = int(sys.stdin.readline())
for _ in range(t):
    print(solve())
